async function answer(value){if(S.feedback?.score===1)return;const t=task(),assisted=S.help;if(t.requires_audio&&!S.heard)return toast('先播放这次的材料，再完成眼前的委托。');let proof=null;if(missingJourneyRequirements(t,S.mission,model()?.tasks,S.attempt).length)return toast('先把前一段委托办妥。');if(t.at_place){if(!journeyNear(S.mapPosition?.player,t.at_place))return toast('先回到对方身边。');proof=(await saveCityPosition(S.mapPosition)).event_id;}let f;try{f=gradeTask(t,value,{assisted});}catch(e){return toast(e.message);}S.feedback=f;S.started=true;if(f.score===0)S.help=true;render();try{await emit('answer',value,t,true,assisted,proof);if(f.score===0)await emit('hint',hintPayload(sourceContext(S.mission,t),'answer_explanation'),t,false);await savePosition();}catch(e){toast('还未存好：'+e.message);}}
async function advance(){
  if(!nextAllowed())return toast('先完成眼前这一步。');if(isRecording())return toast('先停止并保存录音。');
  const t=task();S.started=true;
  if(['learn','source'].includes(t.kind))await emit('view',null);
  if(S.reviewRun){const unit_id=S.reviewRun.unit_id||S.mission.id,review_context={unit_id,mode:S.reviewRun.mode,completed:true},e=await emit('position',{step:S.step,started:S.started,review_context},null,false);await local.put('cache',S.user.id+'|review-run:'+unit_id+':'+S.mission.id,{attempt:S.attempt,step:S.step,task_id:t.id,version:S.mission.version,started:S.started,review_context,at:e.occurred_at});S.progress.review_position=null;S.reviewRun=null;await showGrowth();return;}
  if(S.step>=S.mission.tasks.length-1){S.route='finish';render();void synchronize();return;}
  S.step++;stopPlaying();await prepareTask();render();window.scrollTo(0,0);void savePosition();void prewarm(S.mission);
}
function openDialog(title,html){if(S.dialogPatternView){S.dialogPatternView.destroy();S.dialogPatternView=null;}dialog.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${button('close-dialog','关闭','secondary')}</div><div class="modal-body">${html}</div>`;if(!dialog.open)dialog.showModal();}
async function showGeographicPlace(place){
  const explicit=place.quests||[],items=S.catalog.missions.filter(m=>m.level===S.world&&(explicit.includes(m.id)||m.location===place.scene));
  openDialog(place.zh,`<div class="geography-details"><p class="place-original">${esc(place.cs)}</p><p class="place-chinese">${esc(place.zh)}</p><p>${esc(place.address||'')}</p><small>真实地点与坐标：IPR Praha。这里的声音街、NPC 与经营剧情属于游戏创作。</small></div>${items.length?'<h3>这个地点的故事</h3><div class="mission-grid">'+items.map(missionCard).join('')+'</div>':'<p>这里已能在真实地理世界中探索，专属故事还在制作。</p>'}`);
}
async function showPlace(name){const items=S.catalog.missions.filter(m=>m.level===S.world&&m.location===name);openDialog(name,'<div class="mission-grid">'+items.map(missionCard).join('')+'</div>');}
async function saveCityPosition(city){
  if(!S.user)return;S.mapPosition=city;await local.put('cache',S.user.id+'|city-position',city);
  const m=S.mission||{...recommended(),version:S.catalog.version};
  const event=await queue(m,null,'position',{step:0,started:false,city},S.cityAttempt ||= crypto.randomUUID(),false);void synchronize();return event;
}

function updateJourneyHud(){if(S.route!=='mission'||task()?.kind!=='travel')return;const t=task(),player=S.cityView?.getState()?.player||S.mapPosition?.player,near=journeyNear(player,t.travel.target),missing=missingJourneyRequirements(t,S.mission,model()?.tasks,S.attempt);const text=$('#journey-distance'),confirm=$('#journey-confirm');if(text)text.textContent=player?(near?'已经到目标附近':'还需沿街走近目标'):'正在找到你的角色…';if(confirm)confirm.disabled=!near||!!missing.length||S.feedback?.score===1;}
async function continueJourneyAtNpc(id){if(id!==S.mission?.id)return toast('正在办这份委托，需要时可以回城市自由探索。');if(!journeyNear(S.cityView?.getState()?.player,task().travel.target))return toast('先沿街走到这位伙伴身边。');if(missingJourneyRequirements(task(),S.mission,model()?.tasks,S.attempt).length)return toast('先把前一段委托办妥。');if(S.feedback?.score!==1)await confirmJourney();if(S.feedback?.score===1)await advance();}
async function confirmJourney(){const t=task(),city=S.cityView?.getState();if(!city?.player||!journeyNear(city.player,t.travel.target))return toast('先走到目标附近。');if(missingJourneyRequirements(t,S.mission,model()?.tasks,S.attempt).length)return toast('先把前一段委托办妥。');const position=await saveCityPosition(city),value={player:city.player,place_id:t.travel.target.id,position_event_id:position.event_id},e=await emit('answer',value,t,true);S.feedback=e.feedback;S.started=true;const feedback=$('#journey-feedback'),next=$('#journey-next');if(feedback)feedback.innerHTML=feedbackBox();if(next)next.innerHTML=nextButton();updateJourneyHud();await savePosition();}
async function saveWork(){
  if(S.saveBusy)return;const t=task(),d=S.drafts[draftKey()]||{text:$('#work-answer')?.value||''};if(!d.text?.trim()&&!S.recording?.eventId)return toast('先留下一段文字或真实录音。');
  S.saveBusy=true;try{const e=await emit('work',{text:d.text||'',recording_event_id:S.recording?.eventId||null,...(S.mission.case_board?{citations:S.mission.case_board.sources.filter(s=>S.progress.case_boards?.[S.mission.id]?.[s.id]?.pinned).map(s=>s.id)}:{})});S.lastWork=e.event_id;S.savedWork={event_id:e.event_id,answer:e.answer,assisted:!!e.feedback.assisted,at:e.occurred_at};S.feedback=e.feedback;S.started=true;await savePosition();render();toast('作品已保存；可以做自查或继续故事。');}catch(e){toast('作品还在本机：'+e.message);}finally{S.saveBusy=false;const b=$('[data-action="save-work"]');if(b)b.disabled=false;}}
async function record(){if(isRecording())return;const mission=S.mission,tid=task().id,key=draftKey();try{await startRecording(async(blob,url)=>{try{const r=await queueRecording({id:mission.lesson_id,version:mission.lesson_version},blob);const d=S.drafts[key]||await local.get('drafts',key)||{};S.drafts[key]={...d,blob,recording_event_id:r.event_id};await local.put('drafts',key,S.drafts[key]);if(S.user&&S.mission?.id===mission.id&&task()?.id===tid&&draftKey()===key){S.recording={eventId:r.event_id,url,message:'真实录音已存本机，可以回听。'};render();}void synchronize();}catch(e){toast('录音保存失败：'+e.message);}},message=>{const e=$('[data-record-status]');if(e)e.textContent=message;});render();}catch(e){toast(e.message);}}
async function profile(){const [a,b]=await Promise.all([pending(),simulationPending()]),q=[...a,...b];openDialog('游戏记录',`<p>当前账号：${esc(S.user.username)}</p><p>${q.length} 条游戏记录待同步。原学习账号、笔记与教材保留在同一个服务里。</p>${button('sync','现在同步','gold-button')}${button('reauth','重新登录','secondary')}<p><a href="/">打开原学习系统</a> · <a href="/api/v1/game/export" download>导出游戏记录</a></p>`);}
async function handle(action,el){
  if(action==='close-dialog'){dialog.close();return;}
  if(action==='codex-more'){filterCodex({more:true});return;}
  if(action==='native-transcript'){const source=nativeSource();if(!source)return;await emit('hint','native_transcript',task(),false);S.help=true;openDialog('原声转写与逐段回听','<p>可逐段回听；原转写保留来源中的口语形式。</p><div data-audio-status class="sound-status"></div>'+learningCards(source,'native-card'));return;}
  if(action==='board-focus'){if(!S.mission.case_board?.sources.some(s=>s.id===el.dataset.id))return;S.boardFocus=el.dataset.id;if(task().kind==='evidence'&&S.feedback?.score!==1){S.evidenceSource=el.dataset.id;S.feedback=null;}render();return;}
  if(action==='board-pin'){
    const mission=S.mission,uid=S.user.id;if(!mission.case_board?.sources.some(s=>s.id===el.dataset.id))return;el.disabled=true;
    try{const pinned=!S.progress.case_boards?.[mission.id]?.[el.dataset.id]?.pinned,e=await queue(mission,null,'board',{source:el.dataset.id,pinned},S.attempt,false);if(S.user?.id===uid){applyLocal(e);casePins();void synchronize();}}finally{el.disabled=false;}return;
  }
  if(action==='board-help'||action==='board-transcript'){const id=el.dataset.id;if(!S.mission.case_board?.sources.some(s=>s.id===id))return;const help=S.caseHelp[S.mission.id]||={},source=help[id]||={},field=action==='board-help'?'zh':'transcript';source[field]=!source[field];if(source[field]){S.help=true;await emit('hint',action+':'+id,task(),false);}render();return;}
  if(action==='board-claim-help'){S.boardClaimHelp=true;S.help=true;await emit('hint','claim_translation',task(),false);render();return;}
  if(action==='board-relation'){if(task().kind!=='evidence'||S.feedback?.score===1||!Object.hasOwn(EVIDENCE_RELATIONS,el.dataset.id))return;S.evidenceRelation=el.dataset.id;S.feedback=null;render();return;}
  if(action==='check-evidence'){if(task().kind!=='evidence')return;if(task().requires_audio&&!S.heard)return toast('先点播放，听这段独立原声，再判断它能证明什么。');await answer({source:S.evidenceSource,relation:S.evidenceRelation});return;}
  if(action==='growth'){await showGrowth();return;}
  if(action==='resume-review'){const p=S.progress.review_position,m=S.catalog.missions.find(m=>m.id===p?.mission_id),t=m?.tasks[p.step];if(t)await openReview({...p.review_context,mission_id:m.id,task_id:t.id},{resume:true});return;}
  if(action==='growth-world'){S.growthLevel=el.dataset.level;render();return;}
  if(action==='learning-new'){const unit=S.learningPaths?.units.find(u=>u.id===el.dataset.unit),r=reviewRoute(unit,S.progress);if(r)await openReview(r);return;}
  if(action==='menu'){S.menu=!S.menu;$('.topnav')?.classList.toggle('open',S.menu);return;}
  if(action==='city'){if(isRecording())return toast('先停止并保存录音。');route('city');return;}
  if(action==='world'){S.world=el.dataset.id;route('city');return;}
  if(action==='open-mission'){if(dialog.open)dialog.close();await openMission(el.dataset.id);return;}
  if(action==='open-recommended'){if(dialog.open)dialog.close();await openMission(recommended().id);return;}
  if(action==='sounds'){S.world='Pre-A1';route('city');return;}
  if(action==='codex'||action==='works'||action==='business'){if(isRecording())return toast('先停止并保存录音。');route(action);if(action==='works')void loadWorks().catch(e=>toast(e.message));return;}
  if(action==='work-source'){S.workSource=el.dataset.source;route('works');void loadWorks().catch(e=>toast(e.message));return;}
  if(action==='more-works'){await loadWorks(S.workSource||'course',Number(el.dataset.before));return;}
  if(action==='open-work'){const m=S.catalog.missions.find(m=>m.id===el.dataset.id),i=m?.tasks.findIndex(t=>t.id===el.dataset.task)??-1;if(i<0)return toast('这份作品属于旧版步骤，正文和录音仍保留在作品列表。');await openMission(el.dataset.id,{step:i,workId:el.dataset.work});return;}
  if(action==='business-review'){await syncSimulation(true);await queueSimulation({kind:'review',target:el.dataset.id,rating:el.dataset.rating,work_epoch:Number(el.dataset.epoch)});await syncSimulation();await loadWorks('business');toast('这份经营作品的自查已保存。');return;}
  if(action==='place'){await showPlace(el.dataset.id);return;}
  if(action==='profile'){await profile();return;}
  if(action==='play'){await play(audioRef(el.dataset.source,Number(el.dataset.index)||0),el.dataset.slow==='true');return;}
  if(action==='slow'){S.slow=!S.slow;await play(task().audio||task().cards?.find(c=>c.audio)?.audio||nativeSource()?.audio,S.slow);return;}
  if(action==='hint'){if(!S.hintOpen){const context=sourceContext(S.mission,task());await emit('hint',S.mission.native?'native_transcript':hintPayload(context),task(),false);S.help=true;S.hintOpen=true;}else S.hintOpen=false;render();return;}
  if(action==='task-rule'){const rules=S.catalog.knowledge.filter(g=>g.lesson_id===S.mission.lesson_id),topic=patternTopicFor(S.mission,task());await emit('hint','rule_opened',task(),false,true);S.help=true;openDialog('当前线索的规律',topic?'<div id="pattern-lab-modal"></div><details><summary>展开本课完整资料</summary>'+codexEntries(rules)+'</details>':codexEntries(rules));if(topic)S.dialogPatternView=installPattern($('#pattern-lab-modal'),topic,{modal:true});return;}
  if(action==='answer-option'){if(task().kind==='listen'&&!S.heard)return toast('先点播放，听过这个声音，再选择门。');S.selected=el.dataset.id;await answer(el.dataset.id);return;}
  if(action==='word'){S.words.push({id:el.dataset.id,text:el.dataset.text});S.used.push(el.dataset.id);render();return;}
  if(action==='unword'){const [w]=S.words.splice(Number(el.dataset.index),1);if(w)S.used=S.used.filter(id=>id!==w.id);render();return;}
  if(action==='check-order'){await answer(S.words.map(w=>w.text).join(task().joiner??' '));return;}
  if(action==='meet-npc'){S.cityView?.meetNpc(el.dataset.npcId);document.getElementById('real-pixel-world')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
  if(action==='journey-go'){if(missingJourneyRequirements(task(),S.mission,model()?.tasks,S.attempt).length)return toast('先把前一段委托办妥。');S.cityView?.goTo(task().travel.target.xy,{stopBefore:18});return;}
  if(action==='journey-confirm'){await confirmJourney();return;}
  if(action==='journey-prerequisite'){if(isRecording()){toast('先保存或取消这段录音，再切换任务。');return;}const i=S.mission.tasks.findIndex(t=>t.key===el.dataset.key);if(i>=0){S.step=i;await prepareTask();render();await savePosition();}return;}
  if(action==='next'){await advance();return;}
  if(action==='previous'){if(isRecording())return toast('先保存录音。');if(S.reviewRun){await showGrowth();return;}if(S.step){S.step--;await prepareTask();render();void savePosition();}return;}
  if(action==='restart'){openDialog('重新挑战',`<p>会开启这段故事的新一轮尝试。以前的作品和证据全部保留。</p>${button('restart-confirm','开始新一轮','gold-button')}`);return;}
  if(action==='restart-confirm'){dialog.close();await openMission(S.mission.id,{restart:true});return;}
  if(action==='mission-menu'){openDialog(S.mission.title,`<div class="options">${S.mission.tasks.map((t,i)=>button('jump-step',`${i+1}. ${esc(t.title)}`,'option',`data-index="${i}"`)).join('')}</div>`);return;}
  if(action==='jump-step'){if(isRecording())return toast('先保存录音。');S.reviewRun=null;S.step=Number(el.dataset.index);dialog.close();await prepareTask();render();void savePosition();return;}
  if(action==='dialogue'){const t=task(),oldNode=S.dialogueNode,payload={node_id:oldNode,choice_id:el.dataset.id};if(t.at_place){if(!journeyNear(S.mapPosition?.player,t.at_place))return toast('先回到对方身边。');payload.position_event_id=(await saveCityPosition(S.mapPosition)).event_id;}const e=await emit('dialogue',payload);S.dialogueNode=e.feedback.next;S.feedback=e.feedback;S.started=true;render();void savePosition();return;}
  if(action==='record'){await record();return;}
  if(action==='stop-record'){stopRecording();return;}
  if(action==='save-work'){await saveWork();return;}
  if(action==='self-review'){const related=S.lastWork||model()?.tasks[task().id]?.last_work_id;if(!related)return toast('请先保存这份作品。');await emit('review',{rating:el.dataset.rating,related_event_id:related},task(),false);toast('自查已保存，和系统客观题结果分开记录。');return;}
  if(action==='next-mission'){const i=S.catalog.missions.findIndex(m=>m.id===S.mission.id),parent=S.mission.learning_parent;let next;if(parent&&/^F\d+$/.test(parent))next=S.catalog.missions.find(m=>m.id==='F'+String(Number(parent.slice(1))+1).padStart(2,'0'))||S.catalog.missions.find(m=>m.id==='G-Pre-A1-U01-L01');else if(parent){const main=S.catalog.missions.filter(m=>!m.learning_parent),p=main.findIndex(m=>m.id===parent);next=S.progress.missions.find(m=>m.id===parent)?.complete?main[p+1]:main[p];}else next=S.catalog.missions[i+1];if(next)await openMission(next.id);else route('city');return;}
  if(action==='review'){openDialog('把旧线索带到下一件事里',`<div class="options">${S.progress.review.map(r=>button('review-open',`${esc(S.catalog.missions.find(m=>m.id===r.mission_id)?.title)} · ${r.route?.mode==='new_context'?'新材料':r.route?.mode==='same_material'?'接着这份材料':'旧任务回放'} · ${esc(r.reason)}`,'option',`data-id="${r.mission_id}" data-task="${r.task_id}"`)).join('')}</div>`);return;}
  if(action==='review-open'){const row=S.progress.review.find(r=>r.mission_id===el.dataset.id&&r.task_id===el.dataset.task);await openReview(row?.route||{mission_id:el.dataset.id,task_id:el.dataset.task,mode:'replay'});return;}
  if(action==='export'){const a=document.createElement('a');a.href='/api/v1/game/export';a.download='czech-life-game-export.json';a.click();return;}
  if(action==='sync'){await synchronize();await profile();return;}
  if(action==='reauth'){dialog.close();S.user=null;loginPage();return;}
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled){event.preventDefault();handle(el.dataset.action,el).catch(e=>toast(e.message));}});
document.addEventListener('submit',async event=>{event.preventDefault();if(event.target.id==='login-form'){const form=event.target,b=form.querySelector('button[type="submit"]');b.disabled=true;try{const s=await api('/auth/login',{method:'POST',body:JSON.stringify({username:form.username.value.trim(),password:form.password.value})});await startSession(s);}catch(e){loginPage(e.message);}}else if(event.target.id==='answer-form'){S.typed=$('#answer').value;await answer(S.typed);}});
document.addEventListener('input',event=>{if(event.target.id==='work-answer'){const key=draftKey(),text=event.target.value;S.drafts[key]={...(S.drafts[key]||{}),text,at:new Date().toISOString()};clearTimeout(S.draftTimer);S.draftTimer=setTimeout(()=>local.put('drafts',key,S.drafts[key]).catch(e=>toast('本机草稿还未存好：'+e.message)),120);}if(event.target.id==='answer')S.typed=event.target.value;if(event.target.id==='codex-search')filterCodex();});
document.addEventListener('change',event=>{if(event.target.id==='codex-level')filterCodex();});
document.addEventListener('toggle',event=>{if(event.target.matches?.('[data-native-support]')&&event.target.open&&S.route==='mission'&&S.mission?.native&&document.contains(event.target)){S.help=true;emit('hint','native_transcript',task(),false).catch(e=>toast(e.message));}if(event.target.matches?.('[data-material-view]')&&event.target.open&&S.route==='mission'&&document.contains(event.target)){const context=sourceContext(S.mission,task()),id=event.target.dataset.materialView,key=S.user.id+'|'+S.mission.id+'|'+id+'|'+S.attempt;if(context?.source.id===id&&!S.materialViewed[key]&&model()?.tasks[id]?.view_attempt!==S.attempt){S.materialViewed[key]=true;emit('view',null,context.source,false).catch(e=>toast(e.message));}}if(event.target.matches?.('[data-translation]')&&event.target.open&&S.route==='mission'&&document.contains(event.target)){const id=event.target.dataset.materialId;S.help=true;if(id)S.materialHelps[S.user.id+'|'+S.mission.id+'|'+id+'|'+S.attempt]=true;emit('hint',S.mission?.native?'native_transcript':id?materialHint(id):'translation',task(),false).catch(e=>toast(e.message));}},true);
function filterCodex({more=false}={}){S.codexLimit=more?(S.codexLimit||12)+12:12;const page=codexPageRows(S.catalog.knowledge,{query:$('#codex-search')?.value||'',level:$('#codex-level')?.value||'',limit:S.codexLimit});$('#codex-results').innerHTML=codexEntries(page.items);$('#codex-count').textContent=page.items.length+' / '+page.total+' 条规律';$('#codex-more').hidden=!page.more;}
window.addEventListener('online',()=>{networkState(true);synchronize();void syncSimulation(S.route==='business');});window.addEventListener('offline',()=>networkState(false));window.addEventListener('focus',()=>{if(S.user){void synchronize();void syncSimulation(S.route==='business');}});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&S.user){void synchronize();void syncSimulation(S.route==='business');}});window.addEventListener('beforeunload',e=>{if(isRecording()||S.saveBusy){e.preventDefault();e.returnValue='';}});
boot();







dialog.addEventListener('close',()=>{if(!dialog.open&&S.dialogPatternView){S.dialogPatternView.destroy();S.dialogPatternView=null;}});
